/// 替代collect動效 收球特效
import { Material, Node, NodePool, RealCurve, sp, Sprite, SpriteFrame, tween, Tween, UIOpacity, Vec3 } from 'cc';
import { GameViewAdapter } from './GameViewAdapter';
import AppAssetBundle from '../utils/AppAssetBundle';
import GameConfigManager from '../config/GameConfigManager';

const REFERENCE_DISTANCE = 600;
const MIN_DURATION = 0.12;
const ARC_RATIO = 0.15;
const DEFAULT_BALL_STAGGER = 0.15;

// 球圖縮放 越靠近終點越小 以 REFERENCE_DISTANCE 為一般距離基準
const MUL_SCALE_NEAR = 0.6;
const MUL_SCALE_FAR = 0.9;

const ENABLE_GHOST = true;
const GHOST_INTERVAL = 0.02;
const GHOST_DURATION = 0.35;
const GHOST_OPACITY = 160;
const GHOST_END_SCALE = 0.6;

// aura/glow/flare
const BURST_DURATION = 0.3;
const BURST_START_SCALE = 0.4;
const BURST_END_SCALE = 1.3;
const BURST_START_OPACITY = 220;
// aura > glow
const GLOW_DELAY = 0.12;

// 殘影節點池
const ghostPool = new NodePool();

const COLLECTION_NODE_NAME = 'collectMul'; // 收攏的節點

// 收球起點與終點的 spine 特效 動畫名都是 animation
const COLLECT_START_PATH = 'resources/spine/collect/collect_start';
const COLLECT_END_PATH = 'resources/spine/collect/collect_end';
// 特效縮放 動畫本身比較大
const COLLECT_SPINE_SCALE = 0.5;
// 特效播完沒收到完成回呼時的保底秒數
const COLLECT_SPINE_FALLBACK_SEC = 0.8;

const collectSpineData = new Map<string, Promise<sp.SkeletonData | null>>();

/** 讀取收球特效的 spine 資料 讀過就快取 失敗回 null */
function loadCollectSpineData(path: string): Promise<sp.SkeletonData | null> {
    let task = collectSpineData.get(path);
    if (!task) {
        task = AppAssetBundle.getInstance(GameConfigManager.GAMEID)
            .loadAsset(path, sp.SkeletonData)
            .catch((error) => {
                console.warn(`[CollectMulEffect] 讀取 ${path} 失敗`, error);
                return null;
            });
        collectSpineData.set(path, task);
    }
    return task;
}

/** 在指定位置播一次收球 spine 特效 播完銷毀 */
async function playCollectSpine(adapter: GameViewAdapter, parent: Node, path: string, worldPos: Vec3): Promise<void> {
    const data = await loadCollectSpineData(path);
    if (!data || !parent.isValid) return;

    const node = new Node('collectMulSpine');
    // 程式建出來的節點 layer 不會自動修正 Camera 遮罩會擋掉
    node.layer = adapter.node.layer;
    parent.addChild(node);
    node.setWorldPosition(worldPos);
    node.setScale(COLLECT_SPINE_SCALE, COLLECT_SPINE_SCALE, 1);

    const skeleton = node.addComponent(sp.Skeleton);
    skeleton.premultipliedAlpha = false;
    skeleton.skeletonData = data;
    skeleton.setAnimation(0, 'animation', false);

    const destroy = (): void => {
        if (node.isValid) node.destroy();
    };
    skeleton.setCompleteListener(destroy);
    adapter.scheduleOnce(destroy, COLLECT_SPINE_FALLBACK_SEC);
}

/** 收球特效統一掛在這個容器節點底下（飛行本體、殘影都是），不要各自散在 adapter.node 底下 */
function resolveCollectionRoot(adapter: GameViewAdapter): Node {
    let root = adapter.node.getChildByName(COLLECTION_NODE_NAME);
    if (!root) {
        root = new Node(COLLECTION_NODE_NAME);
        adapter.node.addChild(root);
    }
    return root;
}

export interface CollectMulFlyCell {
    col: number;
    row: number;
}

export interface CollectMulBall extends CollectMulFlyCell {
    val: number;
}

export interface PlayCollectMulFlyForBallsOptions {
    stagger?: number;
    onBallLaunch?: (ball: CollectMulBall, index: number) => void;
    onBallLanded?: (ball: CollectMulBall, index: number) => void;
}

/** 統一建立飛行圖片節點 */
function createVisualNode(name: string, parent: Node, frame: SpriteFrame): Node {
    const node = new Node(name);
    parent.addChild(node);
    node.addComponent(Sprite).spriteFrame = frame;
    return node;
}

/** 取得飛行起點 */
function resolveFromWorld(adapter: GameViewAdapter, cell?: CollectMulFlyCell): Vec3 | null {
    if (cell) {
        const reel = adapter.slotMachineView?.reelViews?.[cell.col];
        return reel?.getCellWorldPosition(cell.row + 2) ?? null;
    }

    return adapter.frameTotalMultiplier?.getWorldPosition() ?? null;
}

/** 依距離調整飛行時間 */
function resolveDuration(adapter: GameViewAdapter, from: Vec3, to: Vec3): number {
    const distance = Vec3.distance(from, to);
    const speed = REFERENCE_DISTANCE / adapter.collectDuration;
    return Math.min(adapter.collectDuration, Math.max(MIN_DURATION, distance / speed));
}

/** 算出這次飛行節奏花費的秒數 */
export function resolveCollectFlyDuration(adapter: GameViewAdapter, cell?: CollectMulFlyCell): number {
    const from = resolveFromWorld(adapter, cell);
    const target = adapter.winBarMulNode;

    if (!from || !target) return 0;

    return resolveDuration(adapter, from, target.getWorldPosition());
}

/** 依距離調整球圖縮放 越靠近終點越小 */
function resolveScale(from: Vec3, to: Vec3): number {
    const distance = Vec3.distance(from, to);
    const t = Math.min(1, distance / REFERENCE_DISTANCE);

    return MUL_SCALE_NEAR + (MUL_SCALE_FAR - MUL_SCALE_NEAR) * t;
}

/** 建立移動曲線 */
function buildMoveEvaluator(curve: RealCurve): (t: number) => number {
    const v0 = curve.evaluate(0);
    const span = curve.evaluate(1) - v0 || 1;

    return (t) => (curve.evaluate(t) - v0) / span;
}

/** 建立高度曲線 */
function buildHeightEvaluator(curve: RealCurve): (t: number) => number {
    const v0 = curve.evaluate(0);
    const v1 = curve.evaluate(1);
    const detrend = (t: number) => curve.evaluate(t) - (v0 + (v1 - v0) * t);

    let peak = 0;
    for (let i = 0; i <= 20; i++) {
        peak = Math.max(peak, Math.abs(detrend(i / 20)));
    }

    return peak < 1e-3 ? (t) => 4 * t * (1 - t) : (t) => detrend(t) / peak;
}

/** 產生殘影，不需要時可直接關閉 ENABLE_GHOST */
function spawnGhost(parent: Node, source: Node, frame: SpriteFrame): void {
    let ghost = ghostPool.get();
    if (ghost) {
        parent.addChild(ghost);
        const sprite = ghost.getComponent(Sprite) ?? ghost.addComponent(Sprite);
        sprite.spriteFrame = frame;
    } else {
        ghost = createVisualNode('collectMulGhost', parent, frame);
    }

    ghost.setWorldPosition(source.getWorldPosition());
    ghost.setWorldRotation(source.worldRotation);
    ghost.setWorldScale(source.worldScale);
    Tween.stopAllByTarget(ghost);

    const opacity = ghost.getComponent(UIOpacity) ?? ghost.addComponent(UIOpacity);
    Tween.stopAllByTarget(opacity);
    opacity.opacity = GHOST_OPACITY;

    tween(opacity).to(GHOST_DURATION, { opacity: 0 }, { easing: 'quadOut' }).start();

    tween(ghost)
        .to(GHOST_DURATION, { scale: new Vec3(GHOST_END_SCALE, GHOST_END_SCALE, 1) })
        .call(() => ghostPool.put(ghost!))
        .start();
}

/**
 * 光暈/閃光 原地放大淡出後銷毀
 * material 黑底去背
 */
function playBurst(parent: Node, worldPos: Vec3, frame: SpriteFrame | null, material?: Material | null): void {
    if (!frame) return;

    const node = createVisualNode('collectMulBurst', parent, frame);
    node.setWorldPosition(worldPos);
    node.setScale(BURST_START_SCALE, BURST_START_SCALE, 1);

    if (material) {
        node.getComponent(Sprite)!.customMaterial = material;
    }

    const opacity = node.addComponent(UIOpacity);
    opacity.opacity = BURST_START_OPACITY;

    tween(node)
        .to(BURST_DURATION, { scale: new Vec3(BURST_END_SCALE, BURST_END_SCALE, 1) }, { easing: 'quadOut' })
        .start();

    tween(opacity)
        .to(BURST_DURATION, { opacity: 0 }, { easing: 'quadOut' })
        .call(() => node.isValid && node.destroy())
        .start();
}

/** 一組組播放 */
function playBurstGroup(parent: Node, worldPos: Vec3, frames: SpriteFrame[], material?: Material | null): void {
    for (const frame of frames) {
        playBurst(parent, worldPos, frame, material);
    }
}

/** 播放單顆收球 */
export function playCollectMulFly(adapter: GameViewAdapter, cell?: CollectMulFlyCell): Promise<void> {
    const from = resolveFromWorld(adapter, cell);
    const target = adapter.winBarMulNode;
    const frame = adapter.collectMulFrame;

    if (!from || !target || !frame) {
        console.warn('[CollectMulEffect] 缺少起點、終點或圖片');
        return Promise.resolve();
    }

    const to = target.getWorldPosition();
    const duration = resolveDuration(adapter, from, to);
    const scale = resolveScale(from, to);
    const moveT = buildMoveEvaluator(adapter.collectMoveCurve);
    const heightT = buildHeightEvaluator(adapter.collectHeightCurve);

    const collectionRoot = resolveCollectionRoot(adapter);
    const node = createVisualNode('collectMulFly', collectionRoot, frame);
    node.setWorldPosition(from);
    node.setScale(scale, scale, 1);

    // 發射瞬間 起點特效
    void playCollectSpine(adapter, collectionRoot, COLLECT_START_PATH, from);
    // 舊的發射光暈 aura glow
    // playBurstGroup(collectionRoot, from, adapter.collectAuraFrames);
    // adapter.scheduleOnce(() => {
    //     playBurstGroup(collectionRoot, from, adapter.collectGlowFrames);
    // }, GLOW_DELAY);

    const dx = to.x - from.x;
    const dy = to.y - from.y;
    const distance = Math.sqrt(dx * dx + dy * dy) || 1;
    const perpX = -dy / distance;
    const perpY = dx / distance;
    const arcHeight = distance * ARC_RATIO;

    const pos = new Vec3();
    const ahead = new Vec3();
    let nextGhostTime = 0;

    const getPosition = (t: number, out: Vec3): void => {
        const move = moveT(t);
        const height = heightT(t);

        out.set(from.x + dx * move + perpX * height * arcHeight, from.y + dy * move + perpY * height * arcHeight, from.z + (to.z - from.z) * move);
    };

    return new Promise<void>((resolve) => {
        tween(node)
            .update(duration, (_target, ratio) => {
                getPosition(ratio, pos);
                node.setWorldPosition(pos);

                // 貼圖朝向飛行方向
                getPosition(Math.min(ratio + 0.02, 1), ahead);
                const faceX = ahead.x - pos.x;
                const faceY = ahead.y - pos.y;

                if (faceX || faceY) {
                    node.angle = (Math.atan2(-faceX, faceY) * 180) / Math.PI;
                }

                // 殘影
                if (ENABLE_GHOST && ratio * duration >= nextGhostTime) {
                    spawnGhost(collectionRoot, node, frame);
                    nextGhostTime = ratio * duration + GHOST_INTERVAL;
                }
            })
            .call(() => {
                // 抵達終點 終點特效
                void playCollectSpine(adapter, collectionRoot, COLLECT_END_PATH, to);
                // 舊的抵達閃光 flare
                // playBurstGroup(collectionRoot, to, adapter.collectFlareFrames, adapter.collectRemoveBlackBgMaterial);
                node.isValid && node.destroy();
                resolve();
            })
            .start();
    });
}

/** 多顆球依序發射 */
export function playCollectMulFlyForBalls(adapter: GameViewAdapter, balls: CollectMulBall[], opts?: PlayCollectMulFlyForBallsOptions): Promise<void> {
    const stagger = opts?.stagger ?? DEFAULT_BALL_STAGGER;

    return Promise.all(
        balls.map(
            (ball, index) =>
                new Promise<void>((resolve) => {
                    adapter.scheduleOnce(async () => {
                        opts?.onBallLaunch?.(ball, index);

                        await playCollectMulFly(adapter, ball);

                        opts?.onBallLanded?.(ball, index);
                        resolve();
                    }, index * stagger);
                })
        )
    ).then(() => undefined);
}
