/**
 * base 層（i18n、audio 等）跨元件事件名稱
 *
 * Producer 與 consumer 引用表，仿照 GameRuntimeEventTypes.ts 的寫法，
 * 作為 mobx 移除計劃 Phase 1 的地基：先建立事件通道，
 * Phase 4 再把 LanguageData/AudioManager/Localized* 的 mobx reaction 換成這裡的事件。
 */
export const BASE_EVENT_TYPE = {
    /** 共用：目前語系變動（LanguageData.currentLanguage） */
    LANGUAGE_CHANGED: 'base/language-changed',
    /** 共用：音樂音量變動（SettingStore.musicVolume） */
    MUSIC_VOLUME_CHANGED: 'base/music-volume-changed',
    /** 共用：音效音量變動（SettingStore.soundVolume） */
    SOUND_VOLUME_CHANGED: 'base/sound-volume-changed',
} as const;

/** base 層事件追蹤編號 */
export const BASE_EVENT_ID = {
    /** 目前語系變動 */
    LANGUAGE_CHANGED: 'EVT-BASE-001',
    /** 音樂音量變動 */
    MUSIC_VOLUME_CHANGED: 'EVT-BASE-002',
    /** 音效音量變動 */
    SOUND_VOLUME_CHANGED: 'EVT-BASE-003',
} as const;

export interface LanguageChangedEvent {
    eventId: typeof BASE_EVENT_ID.LANGUAGE_CHANGED;
    language: string;
}

export interface MusicVolumeChangedEvent {
    eventId: typeof BASE_EVENT_ID.MUSIC_VOLUME_CHANGED;
    musicVolume: number;
}

export interface SoundVolumeChangedEvent {
    eventId: typeof BASE_EVENT_ID.SOUND_VOLUME_CHANGED;
    soundVolume: number;
}

/** 事件名稱與 payload 對照表 */
export interface BaseRuntimeEvents {
    [BASE_EVENT_TYPE.LANGUAGE_CHANGED]: LanguageChangedEvent;
    [BASE_EVENT_TYPE.MUSIC_VOLUME_CHANGED]: MusicVolumeChangedEvent;
    [BASE_EVENT_TYPE.SOUND_VOLUME_CHANGED]: SoundVolumeChangedEvent;
}
